+            && Objects.equals(state, that.state)
+            && Objects.equals(reason, that.reason)
+            && Objects.equals(allocationStatus, that.allocationStatus)
+            && Objects.equals(nodeStats, that.nodeStats);
+    }
+
+    @Override
+    public int hashCode() {
+        return Objects.hash(
+            modelId,
+            modelSize,
+            inferenceThreads,
+            modelThreads,
+            queueCapacity,
+            startTime,
+            nodeStats,
+            state,
+            reason,
+            allocationStatus
+        );
+    }
