+package org.elasticsearch.bootstrap.plugins;
+
+import org.elasticsearch.cli.Terminal;
+import org.elasticsearch.env.Environment;
+import org.elasticsearch.plugins.PluginsSynchronizer;
+
+import java.io.IOException;
