-        <id>es-snapshots</id>
-        <name>elasticsearch snapshot repo</name>
-        <url>https://snapshots.elastic.co/maven/</url>
-    </repository>
-</repositories>
---------------------------------------------------
-
-or in Gradle:
-
-["source","groovy",subs="attributes"]
---------------------------------------------------
-maven {
-        url "https://snapshots.elastic.co/maven/"
-}
---------------------------------------------------
-
-[[java-rest-high-getting-started-maven-maven]]
